-- BC-T01 reference DDL only; SQLite 3, not production database selection.
PRAGMA foreign_keys=ON;
CREATE TABLE scope(tenant TEXT NOT NULL, company TEXT NOT NULL, PRIMARY KEY(tenant,company));
CREATE TABLE source_content(tenant TEXT NOT NULL,company TEXT NOT NULL,id TEXT NOT NULL,sha256 TEXT NOT NULL CHECK(length(sha256)=64),content_text TEXT NOT NULL CHECK(length(content_text) BETWEEN 1 AND 50000),PRIMARY KEY(tenant,company,id),UNIQUE(tenant,company,sha256),FOREIGN KEY(tenant,company) REFERENCES scope);
CREATE TABLE source_origin(tenant TEXT NOT NULL,company TEXT NOT NULL,id TEXT NOT NULL,content_id TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('manual_text','email_text')),provider TEXT,account_ref TEXT,message_id TEXT,author_claim TEXT,PRIMARY KEY(tenant,company,id),UNIQUE(tenant,company,provider,account_ref,message_id),FOREIGN KEY(tenant,company,content_id) REFERENCES source_content(tenant,company,id),CHECK(kind='manual_text' OR (provider IS NOT NULL AND account_ref IS NOT NULL AND message_id IS NOT NULL AND author_claim IS NOT NULL)));
CREATE TABLE source_import(tenant TEXT NOT NULL,company TEXT NOT NULL,id TEXT NOT NULL,origin_id TEXT NOT NULL,actor_id TEXT NOT NULL,imported_at TEXT NOT NULL,PRIMARY KEY(tenant,company,id),FOREIGN KEY(tenant,company,origin_id) REFERENCES source_origin(tenant,company,id));
CREATE TABLE master(tenant TEXT NOT NULL,company TEXT NOT NULL,id TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('customer','contact','supplier','sku')),name TEXT,parent_customer_id TEXT,base_uom TEXT CHECK(base_uom='PCS'),status TEXT NOT NULL CHECK(status IN ('draft','confirmed','inactive')),row_version INTEGER NOT NULL CHECK(row_version>0),PRIMARY KEY(tenant,company,id),FOREIGN KEY(tenant,company) REFERENCES scope,FOREIGN KEY(tenant,company,parent_customer_id) REFERENCES master(tenant,company,id));
CREATE TABLE rfq(tenant TEXT NOT NULL,company TEXT NOT NULL,id TEXT NOT NULL,customer_id TEXT,contact_id TEXT,status TEXT NOT NULL CHECK(status IN ('draft','ready','cancelled','closed')),row_version INTEGER NOT NULL CHECK(row_version>0),unresolved_json TEXT NOT NULL CHECK(json_valid(unresolved_json)),PRIMARY KEY(tenant,company,id),FOREIGN KEY(tenant,company) REFERENCES scope,FOREIGN KEY(tenant,company,customer_id) REFERENCES master(tenant,company,id),FOREIGN KEY(tenant,company,contact_id) REFERENCES master(tenant,company,id));
CREATE TABLE rfq_line(tenant TEXT NOT NULL,company TEXT NOT NULL,rfq_id TEXT NOT NULL,line_id TEXT NOT NULL,sku_id TEXT,quantity TEXT,uom TEXT CHECK(uom='PCS'),requested_item TEXT,source_id TEXT,locator TEXT,PRIMARY KEY(tenant,company,rfq_id,line_id),FOREIGN KEY(tenant,company,rfq_id) REFERENCES rfq(tenant,company,id),FOREIGN KEY(tenant,company,sku_id) REFERENCES master(tenant,company,id),FOREIGN KEY(tenant,company,source_id) REFERENCES source_origin(tenant,company,id));
CREATE TABLE source_use(tenant TEXT NOT NULL,company TEXT NOT NULL,rfq_id TEXT NOT NULL,source_id TEXT NOT NULL,PRIMARY KEY(tenant,company,rfq_id,source_id),FOREIGN KEY(tenant,company,rfq_id) REFERENCES rfq(tenant,company,id),FOREIGN KEY(tenant,company,source_id) REFERENCES source_origin(tenant,company,id));
CREATE TABLE master_evidence(tenant TEXT NOT NULL,company TEXT NOT NULL,master_id TEXT NOT NULL,source_id TEXT NOT NULL,PRIMARY KEY(tenant,company,master_id,source_id),FOREIGN KEY(tenant,company,master_id) REFERENCES master(tenant,company,id),FOREIGN KEY(tenant,company,source_id) REFERENCES source_origin(tenant,company,id));
CREATE TABLE action_result(tenant TEXT NOT NULL,company TEXT NOT NULL,command TEXT NOT NULL,idempotency_key TEXT NOT NULL,request_hash TEXT NOT NULL,action_id TEXT NOT NULL,result_json TEXT NOT NULL CHECK(json_valid(result_json)),PRIMARY KEY(tenant,company,command,idempotency_key),UNIQUE(tenant,company,action_id),FOREIGN KEY(tenant,company) REFERENCES scope);
CREATE TABLE outbox(tenant TEXT NOT NULL,company TEXT NOT NULL,event_id TEXT NOT NULL,action_id TEXT NOT NULL,payload_json TEXT NOT NULL CHECK(json_valid(payload_json)),PRIMARY KEY(tenant,company,event_id),FOREIGN KEY(tenant,company,action_id) REFERENCES action_result(tenant,company,action_id));
-- Cross-field role checks, Decimal positivity, ready assertions, audit and CAS
-- are required command-service guards. DDL alone does not implement them.
-- No UPDATE/DELETE grant for source content/origin/import; append-only via repository.
